import json

ALLOWED_ORIGINS = {"http://localhost:3000", "https://example.com"}
ALLOWED_METHODS = {"GET", "POST", "OPTIONS"}
ALLOWED_HEADERS = {"content-type", "authorization", "x-requested-with", "x-custom-header"}
MAX_AGE = 600
API_PATH = "/api/data"
ALLOW_CREDENTIALS = True

def _normalize_header_name(name): return str(name).strip().lower()

def _parse_list_header(value):
    if not value: return []
    return [item.strip() for item in str(value).split(",") if item.strip()]

def _origin_allowed(origin):
    if origin is None: return False
    origin = str(origin).strip()
    if not origin: return False
    if "*" in ALLOWED_ORIGINS: return True
    return origin in ALLOWED_ORIGINS

def _cors_headers(origin, extra=None):
    headers = {}
    if origin and _origin_allowed(origin):
        if "*" in ALLOWED_ORIGINS:
            headers["Access-Control-Allow-Origin"] = "*"
        else:
            headers["Access-Control-Allow-Origin"] = origin
            headers["Vary"] = "Origin"
        if ALLOW_CREDENTIALS:
            headers["Access-Control-Allow-Credentials"] = "true"
    if extra:
        headers.update(extra)
    return headers

def _json_body(data): return json.dumps(data).encode("utf-8")

def _method_allowed(method): return str(method).upper() in ALLOWED_METHODS

def _headers_allowed(request_headers):
    for header in request_headers:
        if _normalize_header_name(header) not in ALLOWED_HEADERS:
            return False
    return True

def _api_data(method, body):
    if method == "GET":
        return _json_body({"message": "CORS-enabled API response", "method": "GET"})
    if method == "POST":
        try:
            payload = json.loads(body.decode("utf-8")) if body else {}
        except (UnicodeDecodeError, json.JSONDecodeError):
            payload = {"error": "Invalid JSON body"}
        return _json_body({"message": "CORS-enabled API response", "method": "POST", "received": payload})
    return _json_body({"error": "Method not allowed"})

def handle_api_request(method, path, headers, body=b""):
    method = str(method or "GET").upper()
    path = str(path or "/").split("?", 1)[0]
    lower_headers = {}
    for key, value in (headers or {}).items():
        lower_headers[str(key).strip().lower()] = str(value)
    origin = lower_headers.get("origin")

