        return 404, _cors_headers(origin, {"Content-Type": "application/json"}), _json_body({"error": "Not Found"})

    if method == "OPTIONS":
        if not origin or not _origin_allowed(origin):
            return 403, {"Content-Type": "application/json"}, _json_body({"error": "Origin not allowed"})
        requested_method = lower_headers.get("access-control-request-method", "").upper()
        requested_headers = _parse_list_header(lower_headers.get("access-control-request-headers", ""))
        if not requested_method or not _method_allowed(requested_method) or not _headers_allowed(requested_headers):
            return 403, _cors_headers(origin), _json_body({"error": "Preflight request not allowed"})
        preflight_headers = {
            "Access-Control-Allow-Methods": ", ".join(sorted(ALLOWED_METHODS)),
            "Access-Control-Allow-Headers": ", ".join(sorted(ALLOWED_HEADERS)),
            "Access-Control-Max-Age": str(MAX_AGE),
        }
        return 204, _cors_headers(origin, preflight_headers), b""

    if not _method_allowed(method):
        return 405, _cors_headers(origin, {"Allow": ", ".join(sorted(ALLOWED_METHODS)), "Content-Type": "application/json"}), _json_body({"error": "Method not allowed"})

    if origin and not _origin_allowed(origin):
